<article class="rule-card rounded-md border border-slate-200 bg-slate-50 p-4" data-rule-index="{{ $ruleIndex }}">
    <div class="flex items-center justify-between gap-3"><h3 class="font-semibold">Regla</h3><button class="remove-rule min-h-12 rounded-md border border-red-200 px-3 text-sm font-medium text-red-700" type="button">Quitar regla</button></div>
    <div class="mt-3 grid gap-4 md:grid-cols-3">
        <label class="text-sm font-medium md:col-span-2">Identificador estable<input class="mt-1 min-h-12 w-full rounded-md border border-slate-300 px-3" name="coverages[{{ $coverageIndex }}][rules][{{ $ruleIndex }}][id]" value="{{ $rule['id'] ?? '' }}" placeholder="medellin-carros-2026-09" pattern="[A-Za-z0-9][A-Za-z0-9._-]*" required></label>
        <label class="text-sm font-medium">Prioridad<input class="mt-1 min-h-12 w-full rounded-md border border-slate-300 px-3" type="number" min="0" max="100000" name="coverages[{{ $coverageIndex }}][rules][{{ $ruleIndex }}][priority]" value="{{ $rule['priority'] ?? 1000 }}" required></label>
        <label class="text-sm font-medium">Efecto<select class="mt-1 min-h-12 w-full rounded-md border border-slate-300 bg-white px-3" name="coverages[{{ $coverageIndex }}][rules][{{ $ruleIndex }}][effect]" required><option value="restrict" @selected(($rule['effect'] ?? '') === 'restrict')>Restringe</option><option value="allow" @selected(($rule['effect'] ?? '') === 'allow')>Permite</option></select></label>
        <label class="text-sm font-medium">Inicio de vigencia<input class="mt-1 min-h-12 w-full rounded-md border border-slate-300 px-3" type="datetime-local" name="coverages[{{ $coverageIndex }}][rules][{{ $ruleIndex }}][valid_from]" value="{{ $rule['valid_from'] ?? '' }}" required></label>
        <label class="text-sm font-medium">Fin de vigencia <span class="font-normal text-slate-500">(opcional)</span><input class="mt-1 min-h-12 w-full rounded-md border border-slate-300 px-3" type="datetime-local" name="coverages[{{ $coverageIndex }}][rules][{{ $ruleIndex }}][valid_until]" value="{{ $rule['valid_until'] ?? '' }}"></label>
        <label class="text-sm font-medium">Días 1–7 <span class="font-normal text-slate-500">(lunes=1)</span><input class="mt-1 min-h-12 w-full rounded-md border border-slate-300 px-3" name="coverages[{{ $coverageIndex }}][rules][{{ $ruleIndex }}][weekdays]" value="{{ $rule['weekdays'] ?? '' }}" placeholder="1,2,3,4,5"></label>
        <label class="text-sm font-medium">Paridad de fecha<select class="mt-1 min-h-12 w-full rounded-md border border-slate-300 bg-white px-3" name="coverages[{{ $coverageIndex }}][rules][{{ $ruleIndex }}][date_parity]"><option value="">No aplica</option><option value="odd" @selected(($rule['date_parity'] ?? '') === 'odd')>Día impar</option><option value="even" @selected(($rule['date_parity'] ?? '') === 'even')>Día par</option></select></label>
        <label class="text-sm font-medium">Posición del dígito<select class="mt-1 min-h-12 w-full rounded-md border border-slate-300 bg-white px-3" name="coverages[{{ $coverageIndex }}][rules][{{ $ruleIndex }}][digit_position]"><option value="lastNumeric" @selected(($rule['digit_position'] ?? '') === 'lastNumeric')>Último dígito</option><option value="firstNumeric" @selected(($rule['digit_position'] ?? '') === 'firstNumeric')>Primer dígito</option></select></label>
        <label class="text-sm font-medium">Dígitos de placa<input class="mt-1 min-h-12 w-full rounded-md border border-slate-300 px-3" name="coverages[{{ $coverageIndex }}][rules][{{ $ruleIndex }}][digits]" value="{{ $rule['digits'] ?? '' }}" placeholder="0,1,2"></label>
        <label class="text-sm font-medium">Origen de matrícula<input class="mt-1 min-h-12 w-full rounded-md border border-slate-300 px-3" name="coverages[{{ $coverageIndex }}][rules][{{ $ruleIndex }}][registration_origins]" value="{{ $rule['registration_origins'] ?? '' }}" placeholder="local,foreign,unknown"></label>
        <label class="text-sm font-medium md:col-span-2">Horarios <span class="font-normal text-slate-500">(uno por línea, HH:MM-HH:MM)</span><textarea class="mt-1 min-h-24 w-full rounded-md border border-slate-300 p-3" name="coverages[{{ $coverageIndex }}][rules][{{ $ruleIndex }}][time_windows]" required>{{ $rule['time_windows'] ?? '' }}</textarea></label>
        <label class="flex min-h-12 items-center gap-3 self-end rounded-md bg-white px-3 text-sm"><input type="checkbox" name="coverages[{{ $coverageIndex }}][rules][{{ $ruleIndex }}][applies_on_holidays]" value="1" @checked(!empty($rule['applies_on_holidays']))>Aplica en festivos</label>
        <label class="text-sm font-medium md:col-span-2">Fuente HTTPS de la regla<input class="mt-1 min-h-12 w-full rounded-md border border-slate-300 px-3" type="url" name="coverages[{{ $coverageIndex }}][rules][{{ $ruleIndex }}][source_url]" value="{{ $rule['source_url'] ?? '' }}" required></label>
        <label class="text-sm font-medium">Fecha de revisión de la regla<input class="mt-1 min-h-12 w-full rounded-md border border-slate-300 px-3" type="datetime-local" name="coverages[{{ $coverageIndex }}][rules][{{ $ruleIndex }}][verified_at]" value="{{ $rule['verified_at'] ?? '' }}" required></label>
    </div>
</article>
